<?php
namespace App\Http\Controllers;
use App\Models\{AttendanceRecord,DevotionSession,Member};use Illuminate\Database\QueryException;use Illuminate\Http\{JsonResponse,RedirectResponse,Request};use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;use Inertia\{Inertia,Response};
class PublicCheckInController extends Controller {
 public function show(string $token):Response{$session=DevotionSession::where('qr_token',$token)->firstOrFail();return Inertia::render('Public/CheckIn',['session'=>$session->only('name','session_date','start_time','end_time','location','status','qr_token')]);}
 public function search(Request $r,string $token):JsonResponse{$this->openSession($token);$r->validate(['q'=>'required|string|min:2|max:100']);$members=Member::query()->whereIn('status',['new','active'])->search((string)$r->string('q'))->limit(8)->get()->map(fn(Member $m)=>['id'=>$m->id,'name'=>$m->full_name,'initials'=>$m->initials,'email'=>$this->maskEmail($m->email)]);return response()->json(['members'=>$members]);}
 public function checkIn(Request $r,string $token):RedirectResponse{$session=$this->openSession($token);$data=$r->validate(['member_id'=>'required|uuid|exists:members,id']);$member=Member::findOrFail($data['member_id']);$created=$this->record($session,$member);return back()->with($created?'success':'error',$created?'You are checked in. Welcome!':'You were already checked in for this session.');}
 public function register(Request $r,string $token):RedirectResponse{$session=$this->openSession($token);$data=$r->validate(['first_name'=>'required|string|max:100','last_name'=>'required|string|max:100','email'=>'required|email:rfc|max:255|unique:members,email','phone'=>'nullable|string|max:40','address'=>'required|string|max:255','age'=>'required|integer|min:1|max:120','gender'=>['required',Rule::in(['female','male','non_binary','prefer_not_to_say'])]]);DB::transaction(function()use($data,$session){$member=Member::create(['first_name'=>$data['first_name'],'last_name'=>$data['last_name'],'email'=>$data['email'],'phone'=>$data['phone']??null,'address'=>$data['address'],'date_of_birth'=>now()->subYears((int)$data['age'])->startOfYear(),'gender'=>$data['gender'],'join_date'=>today(),'status'=>'new','role'=>'member']);$this->record($session,$member);});return back()->with('success','Welcome! Your profile was created and you are checked in.');}
 private function openSession(string $token):DevotionSession{$session=DevotionSession::where('qr_token',$token)->firstOrFail();abort_unless($session->status==='open',422,'This check-in session is not open.');return $session;}
 private function record(DevotionSession $s,Member $m):bool{try{$record=AttendanceRecord::firstOrCreate(['devotion_session_id'=>$s->id,'member_id'=>$m->id],['attendance_date'=>$s->session_date,'event_type'=>'morning_devotion','status'=>'present','attendee_type'=>'member','check_in_time'=>now(),'check_in_method'=>'qr_code']);return $record->wasRecentlyCreated;}catch(QueryException){return false;}}
 private function maskEmail(?string $email):?string{if(!$email||!str_contains($email,'@'))return null;[$u,$d]=explode('@',$email,2);return substr($u,0,1).str_repeat('•',max(2,strlen($u)-1)).'@'.$d;}
}
